import { defineSchema, defineTable } from "convex/server";
import { v } from "convex/values";

export default defineSchema({
  tasks: defineTable({
    text: v.string(),
    isCompleted: v.boolean(),
  }),
});

import { query, mutation } from "./_generated/server";
import { v } from "convex/values";

export const list = query({
  args: {},
  handler: async (ctx) => {
    return await ctx.db.query("tasks").collect();
  },
});

export const add = mutation({
  args: { text: v.string() },
  handler: async (ctx, args) => {
    await ctx.db.insert("tasks", { text: args.text, isCompleted: false });
  },
});

export const toggle = mutation({
  args: { id: v.id("tasks"), isCompleted: v.boolean() },
  handler: async (ctx, args) => {
    await ctx.db.patch(args.id, { isCompleted: args.isCompleted });
  },
});

export const remove = mutation({
  args: { id: v.id("tasks") },
  handler: async (ctx, args) => {
    await ctx.db.delete(args.id);
  },
});

import { ConvexClient } from "convex/browser";
import { importEnv } from "$lib/env";

const convexUrl = import.meta.env.VITE_CONVEX_URL;

export const client = new ConvexClient(convexUrl);

import { writable } from 'svelte/store';
import { client } from './convex';

export function useQuery(query, args) {
    const { subscribe, set } = writable(undefined);

    // client.onUpdate returns an unsubscribe function
    const unsubscribe = client.onUpdate(query, args, (data) => {
        set(data);
    });

    return { subscribe, unsubscribe };
}

